import React, { useMemo } from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  random,
  interpolate,
  spring,
  Easing,
} from '../remotionShim';
// --- FONT LOADER ---
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;900`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};

// --- SCHEMA ---


export type PartyPackedProps = Record<string, any>;

// --- COMPONENT ---
const PartyPacked: React.FC<PartyPackedProps> = ({
  backgroundColor = "#11001c",
  transparentBackground = false,
  durationInSeconds = 10,
  title = "PARTY IS GETTING PACKED!",
  titleColor = "#ffffff",
  peopleCount = 150,
  partyColors = [
    "#FF0055", // Neon Pink
    "#00FF99", // Neon Green
    "#00CCFF", // Cyan
    "#FFEE00", // Yellow
    "#9900FF", // Purple
  ],
  vibeIntensity = 1,
}) => {
  // Load heavy display font
  useFontLoader(["Anton"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Handle transparency
  const computedBg = transparentBackground ? "transparent" : backgroundColor;

  // Generate "People" (Particles)
  // We use useMemo with the count/width/height dependencies so positions remain stable per render
  // but random enough to look organic.
  const people = useMemo(() => {
    const items = [];
    // safe zone margin
    const marginX = width * 0.05;
    const marginY = height * 0.05;
    
    for (let i = 0; i < peopleCount; i++) {
      const seed = i * 7823; // deterministic seed
      
      // Random position within safe zones
      const x = interpolate(random(seed), [0, 1], [marginX, width - marginX]);
      const y = interpolate(random(seed + 1), [0, 1], [marginY, height - marginY]);
      
      // Random properties
      const size = interpolate(random(seed + 2), [0, 1], [width * 0.02, width * 0.06]);
      const colorIndex = Math.floor(random(seed + 3) * partyColors.length);
      const color = partyColors[colorIndex];
      
      // Entrance timing: Staggered across 80% of the duration
      const totalFrames = durationInSeconds * fps;
      const delay = interpolate(random(seed + 4), [0, 1], [0, totalFrames * 0.8]);
      
      // Individual wiggle characteristics
      const wiggleSpeed = interpolate(random(seed + 5), [0, 1], [0.1, 0.3]) * vibeIntensity;
      const wiggleAmount = interpolate(random(seed + 6), [0, 1], [5, 15]) * vibeIntensity;

      items.push({ x, y, size, color, delay, wiggleSpeed, wiggleAmount });
    }
    
    // Sort by Y so lower items appear "in front" (simple z-indexing)
    items.sort((a, b) => a.y - b.y);
    
    return items;
  }, [peopleCount, width, height, partyColors, durationInSeconds, fps, vibeIntensity]);

  // Title Animation
  const titleSpring = spring({
    frame: frame - fps * 1, // Start 1 second in
    fps,
    config: { damping: 12 },
  });

  const titleScale = interpolate(titleSpring, [0, 1], [0.8, 1]);
  const titleOpacity = interpolate(frame, [0, fps], [0, 1]); // Fade in title early

  return (
    <AbsoluteFill style={{ backgroundColor: computedBg, overflow: "hidden" }}>
      
      {/* 1. Background Pulse (Subtle Disco Floor Vibe) */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `radial-gradient(circle at 50% 50%, ${partyColors[0]}33 0%, transparent 70%)`,
            opacity: interpolate(Math.sin(frame / 10), [-1, 1], [0.5, 0.8]),
          }}
        />
      )}

      {/* 2. The Crowd */}
      {people.map((p, index) => {
        // Entrance Spring
        const entrance = spring({
          frame: frame - p.delay,
          fps,
          config: { mass: 0.5, damping: 12, stiffness: 200 },
        });

        // If not started yet, don't render to save resources
        if (frame < p.delay && entrance === 0) return null;

        // "Dancing" Wiggle
        const danceX = Math.sin((frame + index) * p.wiggleSpeed) * p.wiggleAmount;
        const danceY = Math.cos((frame + index) * p.wiggleSpeed * 1.5) * p.wiggleAmount;

        // Apply scale (0 -> 1)
        const currentSize = p.size * entrance;

        return (
          <div
            key={index}
            style={{
              position: "absolute",
              left: p.x,
              top: p.y,
              width: currentSize,
              height: currentSize,
              borderRadius: "50%",
              backgroundColor: p.color,
              transform: `translate(${danceX}px, ${danceY}px) scale(${entrance})`,
              boxShadow: `0 0 ${currentSize * 0.5}px ${p.color}88`, // Glow
            }}
          />
        );
      })}

      {/* 3. Text Overlay */}
      <div
        style={{
          position: "absolute",
          width: "100%",
          height: "100%",
          display: "flex",
          justifyContent: "center",
          alignItems: "center",
          pointerEvents: "none", // Let clicks pass through if interactive
        }}
      >
        <h1
          style={{
            fontFamily: "Anton, sans-serif",
            fontSize: width * 0.1,
            color: titleColor,
            textAlign: "center",
            textTransform: "uppercase",
            lineHeight: 0.9,
            opacity: titleOpacity,
            transform: `scale(${titleScale})`,
            textShadow: `0 10px 30px rgba(0,0,0,0.5)`,
            margin: 0,
            padding: "0 20px",
            zIndex: 1000,
          }}
        >
          {title}
        </h1>
      </div>
      
    </AbsoluteFill>
  );
};

export default PartyPacked;